    #[test]
    fn terminal_coder_failures_bypass_generic_retries() {
        // A transcript-pump infrastructure failure must not spawn another coder
        // through the generic retry budget, while an ordinary coder error still
        // retries and an auth error stays terminal.
        let pump_failure: Result<()> = Err(anyhow::Error::new(
            crate::transcript_pump::TranscriptPumpError::new("write transcript: broken pipe"),
        ));
        assert!(is_transcript_pump_error(&pump_failure));
        assert!(
            !should_retry_coder_error(&pump_failure),
            "a pump infrastructure failure must not be retried"
        );

        let ordinary: Result<()> = Err(anyhow::anyhow!("Coder exited with code 1"));
        assert!(!is_transcript_pump_error(&ordinary));
        assert!(
            should_retry_coder_error(&ordinary),
            "an ordinary coder error is still retryable"
        );

        let rate_limit: Result<()> = Err(anyhow::Error::new(
            crate::coder::RateLimitExhaustedError::new(1),
        ));
        assert!(
            !should_retry_coder_error(&rate_limit),
            "coder-owned rate-limit exhaustion must bypass the outer retry budget"
        );

        let no_progress: Result<()> = Err(anyhow::Error::new(
            crate::coder::ClaudeNoProgressExhaustedError::new(3),
        ));
        assert!(
            !should_retry_coder_error(&no_progress),
            "bounded Claude no-progress recovery must not multiply through generic retries"
        );
        assert!(matches!(
            classify_task_failure(no_progress.as_ref().unwrap_err()),
            TaskFailure::ProviderUnavailable(message)
                if message.contains("same Task") && message.contains("same Attempt")
        ));

        let cleanup_unconfirmed: Result<()> = Err(anyhow::Error::new(
            crate::coder::ClaudeNoProgressCleanupUnconfirmedError::new("unconfirmed"),
        ));
        assert!(!should_retry_coder_error(&cleanup_unconfirmed));
        assert!(matches!(
            classify_task_failure(cleanup_unconfirmed.as_ref().unwrap_err()),
            TaskFailure::ProviderUnavailable(message)
                if message.contains("cleanup evidence") && message.contains("same Task")
        ));

        let auth: Result<()> = Err(anyhow::Error::new(crate::claude_auth::AuthError::Expired {
            expires_at: 0,
        }));
        assert!(
            !should_retry_coder_error(&auth),
            "an auth error stays terminal for the Task"
        );

        let success: Result<()> = Ok(());
        assert!(!should_retry_coder_error(&success));

        // A supervision-sidecar persistence failure must not be retried: the coder
        // already ran, so relaunching would repeat its side effects.
        let sidecar: Result<()> = {
            let dir = tempfile::tempdir().unwrap();
            let obstruction = dir.path().join("file");
            fs::write(&obstruction, b"x").unwrap();
            let completion = crate::coder::CoderRunCompletion {
                terminal: Ok(0),
                report: nonclean_supervision_report(),
            };
            crate::coder::finish_supervised_coder_run(completion, &obstruction).map(|_| ())
        };
        assert!(is_supervision_sidecar_error(&sidecar));
        assert!(
            !should_retry_coder_error(&sidecar),
            "a supervision-sidecar failure is terminal, never relaunches the coder"
        );
    }

    #[test]
    fn native_pi_owner_failure_bypasses_task_retry() {
        for detail in [
            "native Pi receiver disappeared",
            "native Pi extension stopped reporting to its Task owner",
            "native Pi evidence write failed",
        ] {
            let error = anyhow::Error::new(crate::native_agent::pi_runner::PiNativeTaskError::new(
                anyhow::anyhow!("{detail}"),
            ));
            let result = provider_pause_error(Err(error), CoderKind::Pi, None);
            assert!(!should_retry_coder_error(&result));
            let failure = classify_task_failure(result.as_ref().unwrap_err());
            assert!(matches!(
                failure,
                TaskFailure::ProviderUnavailable(message) if message.contains(detail)
            ));
        }
    }

