    #[test]
    fn phase_preservation_failure_is_not_retried() {
        // B10: when auth/rate-limit recovery cannot preserve prior transcript
        // evidence, `preserve_transcript_phase` returns a typed TranscriptPumpError.
        // The executor must treat that evidence-preservation failure exactly like
        // any pump infrastructure failure: never retried through the generic budget,
        // and classified as a resumable TranscriptPump pause, not a RoundCap.
        let phase_failure: Result<()> = Err(anyhow::Error::new(
            crate::transcript_pump::TranscriptPumpError::new(
                "preserve transcript phase to run.0.jsonl: File exists",
            ),
        ));
        assert!(is_transcript_pump_error(&phase_failure));
        assert!(
            !should_retry_coder_error(&phase_failure),
            "a phase-preservation failure must not be retried through the generic budget"
        );

        match classify_task_failure(phase_failure.as_ref().unwrap_err()) {
            TaskFailure::TranscriptPump(msg) => assert!(
                msg.contains("preserve transcript phase"),
                "the resumable pause must carry the phase-preservation diagnostic: {msg}"
            ),
            _ => panic!(
                "a phase-preservation failure must classify as a resumable TranscriptPump \
                 pause, not a terminal RoundCap"
            ),
        }
    }

    #[test]
    fn transcript_pump_failure_resumes_without_state_repair() {
        // B7: after a transcript-pump failure records its resumable pause, the
        // standard operator resume (reopen_attempt) makes the failed Task directly
        // startable again with NO intervening durable-state repair. The failure
        // never leaves inconsistent state a resume must first fix by hand.
        let tmp = tempfile::TempDir::new().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Pump resume".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        store.create_work_item(&item).unwrap();
        let write_id = store.read_work_item("work-1").unwrap().attempts[0].tasks[0]
            .id
            .clone();

        // A transcript-pump failure records the resumable pause.
        mark_task_failed_attempt_needs_user(
            &store,
            tmp.path(),
            "work-1",
            "attempt-1",
            &write_id,
            &TaskFailure::TranscriptPump("write transcript: broken pipe".to_string()),
            &|_, _| {},
        )
        .unwrap();

        // Before resume the paused Task cannot start — it is durably NeedsUser.
        let rejected = plan_task_start(
            &store,
            "work-1",
            "attempt-1",
            &write_id,
            TaskKind::Write,
            |_| Ok(()),
        );
        assert!(
            rejected.is_err(),
            "a paused Task must not start until it is resumed"
        );

        // The standard resume transition — reopen_attempt — is the ONLY step.
        let mut reopened = store.read_work_item("work-1").unwrap();
        crate::work_model::reopen_attempt(&mut reopened.attempts[0]);
        store.write_work_item(&reopened).unwrap();

        let after = store.read_work_item("work-1").unwrap();
        assert_eq!(after.attempts[0].status, AttemptStatus::Planned);
        assert!(after.attempts[0].pause_kind.is_none());
        assert_eq!(after.attempts[0].tasks[0].status, TaskStatus::Planned);

        // After the reopen the Task starts through the normal path with no repair.
        let plan = plan_task_start(
            &store,
            "work-1",
            "attempt-1",
            &write_id,
            TaskKind::Write,
            |_| Ok(()),
        )
        .expect("a resumed pump-paused Task must be directly startable, no state repair");
        assert_eq!(plan.task.id, write_id);
    }

    #[test]
    fn task_state_persists_when_failure_handoff_cannot_be_written() {
        // B7: the authoritative terminal Task/Attempt state is persisted BEFORE the
        // auxiliary needs-user handoff. When the handoff write fails, the durable
        // transition still holds — the Task is never left Executing by a handoff
        // failure — and the primary failure classification is preserved.
        let tmp = tempfile::TempDir::new().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Handoff obstruction".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        store.create_work_item(&item).unwrap();
        let write_id = store.read_work_item("work-1").unwrap().attempts[0].tasks[0]
            .id
            .clone();

        // Reserve the Task so it is durably Executing before the failure.
        let mut executing = store.read_work_item("work-1").unwrap();
        executing.attempts[0].tasks[0].status = TaskStatus::Executing;
        store.write_work_item(&executing).unwrap();

        // Obstruct the handoff write: pre-create its target path as a directory so
        // `fs::write` fails.
        let handoff_rel = crate::work_model::work_artifact_path(
            "work-1",
            "attempt-1",
            &format!("needs-user-{write_id}.md"),
        );
        let handoff_path = tmp.path().join(&handoff_rel);
        fs::create_dir_all(&handoff_path).unwrap();

        // The terminalization does not fail even though the handoff write cannot land.
        mark_task_failed_attempt_needs_user(
            &store,
            tmp.path(),
            "work-1",
            "attempt-1",
            &write_id,
            &TaskFailure::TranscriptPump("write transcript: disk full".to_string()),
            &|_, _| {},
        )
        .expect("terminalization must not fail because the auxiliary handoff could not be written");

        // The authoritative terminal state IS persisted despite the handoff failure.
        let after = store.read_work_item("work-1").unwrap();
        assert_eq!(
            after.attempts[0].tasks[0].status,
            TaskStatus::NeedsUser,
            "the Task is durably NeedsUser, never left Executing by a handoff failure"
        );
        assert_eq!(after.attempts[0].status, AttemptStatus::NeedsUser);
        assert_eq!(
            after.attempts[0].pause_kind,
            Some(crate::work_model::PauseKind::TranscriptPump),
            "the primary transcript-pump classification is preserved"
        );
    }

    /// A fake coder that records the resolved transcript capture threaded into
    /// `run_captured` and returns success, so a launch route can be checked for
    /// capture threading without a real coder process.
    struct RecordingLearnerCoder {
        recorded: Arc<Mutex<Option<(PathBuf, usize)>>>,
    }

    struct RecordingEnvironmentCoder {
        recorded: Arc<Mutex<Vec<(String, String)>>>,
    }

    struct RecordingWriterPromptCoder {
        recorded: Arc<Mutex<Option<String>>>,
    }

    impl crate::coder::Coder for RecordingWriterPromptCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the writer route launches through the session boundary")
        }

        fn run_captured_reported_session(
            &self,
            prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _capture: Option<&crate::coder::TranscriptCapture<'_>>,
            _session: crate::coder::CoderSession<'_>,
        ) -> crate::coder::CoderRunCompletion {
            *self.recorded.lock().unwrap() = Some(prompt.to_string());
            crate::coder::CoderRunCompletion {
                terminal: Ok(0),
                report: Default::default(),
            }
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the writer route never runs interactively")
        }
    }

    impl crate::coder::Coder for RecordingEnvironmentCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the writer route launches through run_captured")
        }

        fn run_captured(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            extra_env: &[(String, String)],
            _capture: Option<&crate::coder::TranscriptCapture<'_>>,
        ) -> Result<i32> {
            *self.recorded.lock().unwrap() = extra_env.to_vec();
            Ok(0)
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the writer route never runs interactively")
        }
    }

    impl crate::coder::Coder for RecordingLearnerCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the learner route launches through run_captured")
        }

        fn run_captured(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            capture: Option<&crate::coder::TranscriptCapture<'_>>,
        ) -> Result<i32> {
            if let Some(capture) = capture {
                *self.recorded.lock().unwrap() = Some((
                    capture.path.to_path_buf(),
                    capture.config.console_preview_limit,
                ));
            }
            Ok(0)
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the learner route never runs interactively")
        }
    }

    #[test]
    fn learner_launch_threads_resolved_capture() {
        // B8: the Learner launch route threads the project's resolved, immutable
        // TranscriptCapture into run_captured — not a dropped or default config. A
        // distinctive project console-preview-limit must arrive at the coder
        // verbatim; this fails if the route drops or re-resolves the capture.
        let tmp = tempfile::tempdir().unwrap();
        let project_root = tmp.path();
        let config_dir = project_root.join(".fluent");
        fs::create_dir_all(&config_dir).unwrap();
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 7777\n",
        )
        .unwrap();

        let workspace = project_root.join("workspace");
        fs::create_dir_all(&workspace).unwrap();
        let handoff_dir = project_root.join("handoff");
        fs::create_dir_all(&handoff_dir).unwrap();
        let transcript_path = project_root.join("learner-transcript.jsonl");
        let resolver = ContentResolver::new(None);

        let recorded = Arc::new(Mutex::new(None));
        let recorded_for_coder = Arc::clone(&recorded);
        // Resolve the capture the way the production adapter does — through the
        // public constructor, from the transcript path and project root.
        let capture = crate::coder::TranscriptCapture::new(&transcript_path, project_root);
        run_learner_with_coder(
            LearnerRunInputs {
                native_identity: None,
                workspace_path: &workspace,
                resolver: &resolver,
                extra_args: &[],
                coder_kind: CoderKind::Codex,
                // no_sandbox with a pre-land (not handoff-only) run keeps the launch
                // effectively unsandboxed, so no credential/Seatbelt setup is needed.
                no_sandbox: true,
                model: None,
                effort: None,
                review_artifact_paths: &[],
                tester_artifact_paths: &[],
                diff_command: "git diff",
                handoff_dir: &handoff_dir,
                denied_write_roots: &[],
                handoff_only: false,
                repair: None,
            },
            LearnerExecutionMode::Capture,
            Some(capture),
            HostPreparation::Production,
            move |_sandbox, _executable| {
                Box::new(RecordingLearnerCoder {
                    recorded: recorded_for_coder,
                })
            },
        )
        .expect("the learner launch runs the injected coder");

        let recorded = recorded.lock().unwrap();
        let (path, limit) = recorded
            .as_ref()
            .expect("the learner route must pass a capture to run_captured, not drop it");
        assert_eq!(
            path, &transcript_path,
            "the capture must carry the learner transcript path"
        );
        assert_eq!(
            *limit, 7777,
            "the resolved project pump threshold must be threaded verbatim, not defaulted"
        );
    }

