    #[test]
    fn only_managed_home_claude_launches_need_the_unsandboxed_credential_bridge() {
        let home = Path::new("managed-claude-home");

        assert!(needs_managed_claude_credential_bridge(
            CoderKind::Claude,
            Some(home)
        ));
        assert!(!needs_managed_claude_credential_bridge(
            CoderKind::Claude,
            None
        ));
        assert!(!needs_managed_claude_credential_bridge(
            CoderKind::Codex,
            Some(home)
        ));
    }

