    #[test]
    fn writer_launch_threads_resolved_capture() {
        // B8: the Writer launch route (`run_task_coder`) threads the project's
        // resolved, immutable TranscriptCapture into run_captured — a distinctive
        // project console-preview-limit must arrive at the coder verbatim, and the
        // capture must carry the write Task's transcript path. This fails if the route
        // drops, defaults, or re-resolves the capture.
        let tmp = tempfile::tempdir().unwrap();
        let project_root = tmp.path();
        let config_dir = project_root.join(".fluent");
        fs::create_dir_all(&config_dir).unwrap();
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 7777\n",
        )
        .unwrap();

        // A workspace whose expertise INDEX already exists, so the route skips seeding
        // the project model (which would otherwise launch a real coder).
        let workspace = project_root.join("workspace");
        fs::create_dir_all(workspace.join(".fluent/expertise")).unwrap();
        fs::write(workspace.join(".fluent/expertise/INDEX.md"), "# Index\n").unwrap();

        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Writer capture".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        let artifact_area = item.attempts[0].tasks[0]
            .artifact_area
            .as_ref()
            .unwrap()
            .path
            .clone();
        let expected_transcript = project_root.join(&artifact_area).join("transcript.jsonl");

        let resolver = ContentResolver::new(Some(project_root));
        let recorded = Arc::new(Mutex::new(None));
        let recorded_for_coder = Arc::clone(&recorded);
        let pump_config = crate::transcript_pump::resolve_config(project_root);
        run_task_coder_with_coder(
            &item,
            "attempt-1",
            "attempt-1-write-1",
            project_root,
            &workspace,
            &[],
            &resolver,
            &[],
            CoderKind::Codex,
            true,
            None,
            None,
            &pump_config,
            None,
            None,
            &test_writer_cache(project_root),
            None,
            move |_sandbox, _executable| {
                Box::new(RecordingLearnerCoder {
                    recorded: recorded_for_coder,
                })
            },
        )
        .expect("the writer launch runs the injected coder");

        let recorded = recorded.lock().unwrap();
        let (path, limit) = recorded
            .as_ref()
            .expect("the writer route must pass a capture to run_captured, not drop it");
        assert_eq!(
            path, &expected_transcript,
            "the capture must carry the write Task's transcript path"
        );
        assert_eq!(
            *limit, 7777,
            "the resolved project pump threshold must be threaded verbatim, not defaulted"
        );
    }

    #[test]
    fn writer_retry_reuses_resolved_capture_after_config_change() {
        // B8: `run_write_task` resolves the capture config once, before its retry loop,
        // and threads the same immutable config into every attempt. Prove the launch
        // route honors that immutable config rather than re-resolving: resolve once at
        // 7777, change the on-disk config to 4321, then launch (as a retry would) and
        // assert the capture still carries 7777 — a config change between attempts can
        // never swap this role's capture mid-run.
        let tmp = tempfile::tempdir().unwrap();
        let project_root = tmp.path();
        let config_dir = project_root.join(".fluent");
        fs::create_dir_all(&config_dir).unwrap();
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 7777\n",
        )
        .unwrap();

        let workspace = project_root.join("workspace");
        fs::create_dir_all(workspace.join(".fluent/expertise")).unwrap();
        fs::write(workspace.join(".fluent/expertise/INDEX.md"), "# Index\n").unwrap();

        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Writer capture".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();

        let resolver = ContentResolver::new(Some(project_root));
        // Resolve once, exactly as `run_write_task` does before its retry loop.
        let pump_config = crate::transcript_pump::resolve_config(project_root);
        // A config change lands between the initial attempt and the retry.
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 4321\n",
        )
        .unwrap();

        let recorded = Arc::new(Mutex::new(None));
        let recorded_for_coder = Arc::clone(&recorded);
        run_task_coder_with_coder(
            &item,
            "attempt-1",
            "attempt-1-write-1",
            project_root,
            &workspace,
            &[],
            &resolver,
            &[],
            CoderKind::Codex,
            true,
            None,
            None,
            &pump_config,
            None,
            None,
            &test_writer_cache(project_root),
            None,
            move |_sandbox, _executable| {
                Box::new(RecordingLearnerCoder {
                    recorded: recorded_for_coder,
                })
            },
        )
        .expect("the writer retry launch runs the injected coder");

        let recorded = recorded.lock().unwrap();
        let (_path, limit) = recorded
            .as_ref()
            .expect("the writer route must pass a capture to run_captured");
        assert_eq!(
            *limit, 7777,
            "the retry threads the resolve-once config, not the changed on-disk 4321"
        );
    }

    /// A one-launch non-clean supervision report (a reaped leader whose group could not
    /// be verifiably swept), for driving the production sidecar boundary.
    fn nonclean_supervision_report() -> crate::coder::CoderSupervisionReport {
        crate::coder::CoderSupervisionReport {
            launches: vec![crate::coder::CoderLaunchSupervision {
                exit_code: Some(0),
                group_sweep: crate::coder::GroupSweepDisposition::Unconfirmed(
                    crate::coder::ProcessOpDiagnostic {
                        operation: "kill process group".to_string(),
                        kind: Some("PermissionDenied".to_string()),
                        errno: Some(1),
                        message: Some("Operation not permitted".to_string()),
                    },
                ),
                provider_liveness: None,
            }],
        }
    }

    /// An injected coder that reports a non-clean supervision report (a reaped leader
    /// whose group could not be verifiably swept), so the production role boundary must
    /// persist it as a sidecar.
    struct SupervisionReportingCoder {
        recorded_dir: Arc<Mutex<Option<PathBuf>>>,
    }

    struct SessionRecordingCoder {
        recorded: Arc<Mutex<Option<String>>>,
    }

    impl crate::coder::Coder for SessionRecordingCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the writer route launches through the session boundary")
        }

        fn run_captured_reported_session(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _capture: Option<&crate::coder::TranscriptCapture<'_>>,
            session: crate::coder::CoderSession<'_>,
        ) -> crate::coder::CoderRunCompletion {
            let value = match session {
                crate::coder::CoderSession::FreshPersistent => "fresh".to_string(),
                crate::coder::CoderSession::Resume(id) => format!("resume:{id}"),
                crate::coder::CoderSession::Ephemeral => "ephemeral".to_string(),
            };
            *self.recorded.lock().unwrap() = Some(value);
            crate::coder::CoderRunCompletion {
                terminal: Ok(0),
                report: Default::default(),
            }
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the writer route never runs interactively")
        }
    }

