    #[test]
    fn reviewer_retry_reuses_resolved_capture_after_config_change() {
        // B8: `run_review_task` resolves the capture config once, before its retry
        // loop, and threads the same immutable config into every attempt. Prove the
        // launch route honors that immutable config rather than re-resolving: resolve
        // once at 7777, change the on-disk config to 4321, then launch (as a retry
        // would) and assert the capture still carries 7777.
        let tmp = tempfile::tempdir().unwrap();
        let project_root = tmp.path();
        let config_dir = project_root.join(".fluent");
        fs::create_dir_all(&config_dir).unwrap();
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 7777\n",
        )
        .unwrap();

        let item = review_item_with_role("architecture");
        let review_task_id = item.attempts[0]
            .tasks
            .iter()
            .find(|t| t.role == "architecture")
            .expect("the architecture review task exists")
            .id
            .clone();

        let artifact_dir = project_root.join("artifacts");
        fs::create_dir_all(&artifact_dir).unwrap();
        let review_path = artifact_dir.join("review.md");

        let resolver = ContentResolver::new(Some(project_root));
        // Resolve once, exactly as `run_review_task` does before its retry loop.
        let pump_config = crate::transcript_pump::resolve_config(project_root);
        // A config change lands between the initial attempt and the retry.
        fs::write(
            config_dir.join("config.yaml"),
            "transcript:\n  console-preview-limit: 4321\n",
        )
        .unwrap();

        let recorded = Arc::new(Mutex::new(None));
        let recorded_for_coder = Arc::clone(&recorded);
        run_review_coder_with_coder(
            &item,
            "attempt-1",
            &review_task_id,
            project_root,
            &artifact_dir,
            &review_path,
            &[],
            &[],
            false,
            &resolver,
            &[],
            CoderKind::Codex,
            true,
            None,
            None,
            &pump_config,
            None,
            None,
            move |_sandbox, _executable| {
                Box::new(RecordingLearnerCoder {
                    recorded: recorded_for_coder,
                })
            },
        )
        .expect("the reviewer retry launch runs the injected coder");

        let recorded = recorded.lock().unwrap();
        let (_path, limit) = recorded
            .as_ref()
            .expect("the reviewer route must pass a capture to run_captured");
        assert_eq!(
            *limit, 7777,
            "the retry threads the resolve-once config, not the changed on-disk 4321"
        );
    }

    #[test]
    fn writer_assignment_safety_setup_rollback_preserves_assignment() {
        let tmp = tempfile::tempdir().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = WorkItem::planned("work-1", "Rollback the Writer reservation");
        item.add_initial_attempt("attempt-1").unwrap();
        let source = &mut item.attempts[0].tasks[0];
        let workspace = source.workspace_access.writes[0].clone();
        source.status = TaskStatus::Complete;
        source.output = Some(TaskOutput {
            workspace_id: workspace.id.clone(),
            workspace_path: workspace.path.clone(),
            source_branch: "main".into(),
            base_commit: None,
            commit: "commit-initial".into(),
            no_change: None,
            learner_canonicalization: None,
        });
        item.attempts[0].status = AttemptStatus::Reviewing;
        let evidence = ArtifactRef {
            producer_id: "review-tests".into(),
            path: work_artifact_path("work-1", "attempt-1", "review-tests/review.md"),
        };
        let writer_task_id = item
            .add_next_write_round("attempt-1", vec![evidence.clone()])
            .unwrap();
        item.attempts[0].tasks[1].writer_correction_assignment = Some(WriterCorrectionAssignment {
            schema_version: WRITER_CORRECTION_ASSIGNMENT_SCHEMA_VERSION,
            work_item_id: "work-1".into(),
            attempt_id: "attempt-1".into(),
            writer_task_id,
            source_task_id: "attempt-1-write-1".into(),
            source_candidate_commit: "commit-initial".into(),
            source_task_inputs: Vec::new(),
            evidence: vec![WriterCorrectionAssignmentInput {
                artifact: evidence.clone(),
                digest: format!("sha256:{}", "3".repeat(64)),
            }],
            findings: vec![WriterCompletionFinding {
                id: "finding:tests:rollback".into(),
                role: "tests".into(),
                source: evidence.path.clone(),
                requirement: "Keep the assignment during rollback".into(),
            }],
            origin: WriterCorrectionAssignmentOrigin::Captured,
        });
        item.validate().unwrap();
        store.create_work_item(&item).unwrap();

        let mut executing = store.read_work_item("work-1").unwrap();
        let prior_task = executing.attempts[0].tasks[1].clone();
        let prior_assignment = prior_task.writer_correction_assignment.clone().unwrap();
        let prior_attempt_status = executing.attempts[0].status.clone();
        let prior_attempt_pause = executing.attempts[0].pause_kind.clone();
        let prior_attempt_completed_at = executing.attempts[0].completed_at.clone();
        let mut written_task = prior_task.clone();
        written_task.status = TaskStatus::Executing;
        written_task.started_at = Some("2026-09-11T00:00:00Z".into());
        executing.attempts[0].tasks[1] = written_task.clone();
        executing.attempts[0].status = AttemptStatus::Executing;
        store.write_work_item(&executing).unwrap();

        let receipt = ReservationReceipt {
            prior_task,
            prior_attempt_status,
            prior_attempt_pause,
            prior_attempt_completed_at,
            written_task,
            written_attempt_status: AttemptStatus::Executing,
            written_attempt_pause: executing.attempts[0].pause_kind.clone(),
            written_attempt_completed_at: executing.attempts[0].completed_at.clone(),
        };
        let error = with_reservation_rollback(
            &store,
            "work-1",
            "attempt-1",
            "attempt-1-write-2",
            &receipt,
            || Err::<(), _>(anyhow::anyhow!("post-reservation setup failed")),
        )
        .expect_err("setup failure should return after restoring its reservation");
        assert_eq!(error.to_string(), "post-reservation setup failed");

        let restored = store.read_work_item("work-1").unwrap();
        assert_eq!(
            restored.attempts[0].tasks[1]
                .writer_correction_assignment
                .as_ref(),
            Some(&prior_assignment),
            "rollback restores execution state without dropping host-owned authority"
        );
        assert_eq!(restored.attempts[0].tasks[1].status, TaskStatus::Planned);
        assert_eq!(restored.attempts[0].tasks[1].started_at, None);
        assert_eq!(restored.attempts[0].status, AttemptStatus::Planned);
    }

    #[test]
    fn reservation_rollback_failure_composes_downcastable_secondary() {
        // When post-reservation setup fails AND the CAS rollback cannot be persisted,
        // both the typed primary and the typed storage secondary must stay
        // downcastable — the rollback failure is composed structurally, not flattened
        // into the primary's message.
        let tmp = tempfile::tempdir().unwrap();
        let store = WorkModelStore::new(tmp.path());

        // Build a receipt from a real Task shape, but never write the Work Item to the
        // store, so the rollback's `mutate_work_item` fails to read it and returns a
        // typed `WorkModelStorageError`.
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Rollback compose".to_string(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        let task = item.attempts[0].tasks[0].clone();
        let receipt = ReservationReceipt {
            prior_task: task.clone(),
            prior_attempt_status: AttemptStatus::Planned,
            prior_attempt_pause: None,
            prior_attempt_completed_at: None,
            written_task: task.clone(),
            written_attempt_status: AttemptStatus::Executing,
            written_attempt_pause: None,
            written_attempt_completed_at: None,
        };

        let err = with_reservation_rollback(
            &store,
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            &receipt,
            || {
                Err::<(), _>(anyhow::Error::new(
                    crate::transcript_pump::TranscriptPumpError::new(
                        "post-reservation setup failed",
                    ),
                ))
            },
        )
        .expect_err("setup failed and the absent Work Item cannot be rolled back");

        assert!(
            err.downcast_ref::<crate::transcript_pump::TranscriptPumpError>()
                .is_some(),
            "the typed primary setup fault stays downcastable, never masked: {err:#}"
        );
        assert!(
            err.downcast_ref::<WorkModelStorageError>().is_some(),
            "the rollback persistence failure is retained as a downcastable secondary: {err:#}"
        );
    }

    #[test]
    fn rollback_reservation_fails_on_a_missing_entity() {
        // The reservation wrote this exact Task, so a structurally missing entity
        // during rollback is a model-integrity fault, not a silently-successful no-op.
        let tmp = tempfile::tempdir().unwrap();
        let store = WorkModelStore::new(tmp.path());

        // Persist a Work Item that has NO matching attempt/task.
        let item = WorkItem {
            id: "work-1".to_string(),
            title: "Missing entity".to_string(),
            ..Default::default()
        };
        store.write_work_item(&item).unwrap();

        // A receipt built from an unrelated Task shape; the rollback reducer will not
        // find the reserved Attempt/Task in the persisted item.
        let mut shaped = WorkItem {
            id: "work-1".to_string(),
            title: "Missing entity".to_string(),
            ..Default::default()
        };
        shaped.add_initial_attempt("attempt-1").unwrap();
        let task = shaped.attempts[0].tasks[0].clone();
        let receipt = ReservationReceipt {
            prior_task: task.clone(),
            prior_attempt_status: AttemptStatus::Planned,
            prior_attempt_pause: None,
            prior_attempt_completed_at: None,
            written_task: task.clone(),
            written_attempt_status: AttemptStatus::Executing,
            written_attempt_pause: None,
            written_attempt_completed_at: None,
        };

        let err =
            rollback_reservation(&store, "work-1", "attempt-1", "attempt-1-write-1", &receipt)
                .expect_err("a structurally missing reserved entity fails the rollback");
        // The reducer's model error surfaces as a typed storage error, never a clean Ok.
        assert!(
            matches!(err, WorkModelStorageError::InvalidModel { .. }),
            "a missing entity is a typed model-integrity failure: {err}"
        );
    }

    #[test]
    fn reviewer_preserves_pump_and_cleanup_failures() {
        // B7: when a Reviewer's coder run fails with a typed transcript-pump
        // primary AND its workspace-confinement cleanup also fails, the composed
        // outcome durably terminalizes the Task, preserves the typed pump primary
        // (still discoverable by downcast, so it classifies as a resumable
        // transcript-pump pause rather than a generic failure), and retains the
        // cleanup failure as secondary context rather than masking the primary.
        let tmp = tempfile::TempDir::new().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Reviewer composite failure".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        // Reserve a Review Task Executing under a Reviewing Attempt.
        let review_task = crate::work_model::Task {
            id: "attempt-1-review-architecture".to_string(),
            kind: TaskKind::Review,
            status: TaskStatus::Executing,
            role: "architecture".to_string(),
            instructions: None,
            work_item_id: "work-1".to_string(),
            attempt_id: Some("attempt-1".to_string()),
            workspace_access: crate::work_model::WorkspaceAccess {
                reads: vec![crate::work_model::WorkspaceRef {
                    id: "candidate".to_string(),
                    path: "candidate-workspace".to_string(),
                }],
                writes: Vec::new(),
            },
            artifact_area: Some(crate::work_model::TaskArtifactArea {
                path: crate::work_model::work_artifact_path(
                    "work-1",
                    "attempt-1",
                    "attempt-1-review-architecture",
                ),
            }),
            review_context: Some(crate::work_model::ReviewContext {
                candidate_workspace_id: "candidate".to_string(),
                candidate_workspace_path: "candidate-workspace".to_string(),
                source_branch: "work/attempt-1".to_string(),
                candidate_commit: "abc123".to_string(),
                base_commit: None,
            }),
            writer_correction_assignment: None,
            verification_context: None,
            evidence_review_context: None,
            input_artifacts: Vec::new(),
            depends_on: None,
            output: None,
            created_at: None,
            started_at: None,
            completed_at: None,
        };
        item.attempts[0].tasks.push(review_task);
        item.attempts[0].status = AttemptStatus::Reviewing;
        store.create_work_item(&item).unwrap();

        let resolver = ContentResolver::new(None);
        let config = WorkTaskRunConfig {
            project_root: tmp.path(),
            store: &store,
            work_item_id: "work-1",
            attempt_id: "attempt-1",
            task_id: "attempt-1-review-architecture",
            resolver: &resolver,
            extra_args: &[],
            no_sandbox: true,
            store_lock: None,
        };

        let pump_primary: Result<()> = Err(anyhow::Error::new(
            crate::transcript_pump::TranscriptPumpError::new(
                "write transcript-pump status: no space left on device",
            ),
        ));
        let cleanup_failure: Result<()> = Err(anyhow::anyhow!(
            "restore reviewer worktree confinement failed"
        ));

        let error = finalize_review_outcome(
            &config,
            pump_primary,
            cleanup_failure,
            &tmp.path().join("does-not-exist-review.md"),
            &tmp.path().join("does-not-exist-review-inspection.json"),
            &tmp.path().join("does-not-exist-transcript.jsonl"),
            false,
            &tmp.path().join("candidate-workspace"),
            "abc123",
            "architecture",
            &|_, _| {},
        )
        .expect_err("a composite coder+cleanup failure must return an error");

        // The typed pump primary survives composition and stays downcastable.
        assert!(
            error
                .downcast_ref::<crate::transcript_pump::TranscriptPumpError>()
                .is_some(),
            "the transcript-pump primary must remain discoverable by downcast, not be masked by cleanup"
        );
        // The cleanup failure is retained as secondary context.
        let rendered = format!("{error:#}");
        assert!(
            rendered.contains("restore reviewer worktree confinement failed"),
            "the cleanup failure must be retained as secondary context: {rendered}"
        );

        // The Task is durably terminalized as a resumable transcript-pump pause,
        // never left Executing, and classified from the preserved typed primary.
        let after = store.read_work_item("work-1").unwrap();
        let review = after.attempts[0]
            .tasks
            .iter()
            .find(|t| t.id == "attempt-1-review-architecture")
            .unwrap();
        assert_eq!(
            review.status,
            TaskStatus::NeedsUser,
            "the Review Task is durably terminalized, never left Executing"
        );
        assert_eq!(
            after.attempts[0].pause_kind,
            Some(crate::work_model::PauseKind::TranscriptPump),
            "the preserved typed pump primary classifies the pause, not the cleanup failure"
        );
    }

    #[cfg(unix)]
    #[test]
    fn prepare_pre_review_reclaims_only_canonical_cache_dirs() {
        let tmp = tempfile::tempdir().unwrap();
        let project = tmp.path();
        let artifact_relative =
            crate::work_model::work_artifact_path("work-1", "attempt-1", "review-1");
        let artifact = project.join(&artifact_relative);
        let cache = candidate_reviewer_cache_dir(project, "abc123");
        fs::create_dir_all(&artifact).unwrap();
        fs::create_dir_all(project.join(".fluent/hooks")).unwrap();
        fs::create_dir_all(project.join(".fluent")).unwrap();
        fs::write(
            project.join(".fluent/config.yaml"),
            "reviewer-cache:\n  max-project-gib: 0\n  min-free-gib: 0\n",
        )
        .unwrap();
        let hook = project.join(".fluent/hooks/prepare-pre-review");
        fs::write(
            &hook,
            "#!/bin/sh\nmkdir -p \"$FLUENT_REVIEWER_ARTIFACT_DIR/target\"\nprintf cache > \"$FLUENT_REVIEWER_ARTIFACT_DIR/target/output\"\nprintf evidence > \"$FLUENT_REVIEWER_ARTIFACT_DIR/hook-note\"\n",
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        let mut permissions = fs::metadata(&hook).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&hook, permissions).unwrap();

        let store = WorkModelStore::new(project);
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Hook cache".to_string(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        let task = &mut item.attempts[0].tasks[0];
        task.id = "review-1".to_string();
        task.kind = TaskKind::Review;
        task.status = TaskStatus::Executing;
        task.workspace_access.writes.clear();
        task.workspace_access.reads.push(WorkspaceRef {
            id: "candidate".to_string(),
            path: "candidate".to_string(),
        });
        task.review_context = Some(crate::work_model::ReviewContext {
            candidate_workspace_id: "candidate".to_string(),
            candidate_workspace_path: "candidate".to_string(),
            source_branch: "main".to_string(),
            candidate_commit: "abc123".to_string(),
            base_commit: None,
        });
        task.artifact_area = Some(crate::work_model::TaskArtifactArea {
            path: artifact_relative,
        });
        store.create_work_item(&item).unwrap();

        prepare_reviewer_hook_cache(
            project,
            project,
            &artifact,
            &cache,
            "work-1",
            "attempt-1",
            "review-1",
            &FilesystemReviewerCacheAdmission,
            &report_reviewer_cache,
        );

        assert!(artifact.join("hook-note").is_file());
        assert!(
            !artifact.join("target").exists(),
            "over-budget hook cache must be removed while noncanonical output remains"
        );
    }

