    /// A reviewer coder that mutates a tracked source file and locks the git index,
    /// then faults with a typed transcript-pump primary, so the real source-checkout
    /// confinement guard's RESTORE (`git restore --staged --worktree`) genuinely fails
    /// on the lock. It counts its launches so the test can assert the pump fault is not
    /// retried. This drives the composite failure through the production route rather
    /// than fabricating finalizer inputs.
    struct SourceRestoreFaultCoder {
        source_root: PathBuf,
        launches: Arc<Mutex<usize>>,
    }

    impl crate::coder::Coder for SourceRestoreFaultCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the review route launches through run_captured")
        }

        fn run_captured(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _capture: Option<&crate::coder::TranscriptCapture<'_>>,
        ) -> Result<i32> {
            *self.launches.lock().unwrap() += 1;
            // Mutate a tracked (non-Fluent) source file so the guard detects a change,
            // then hold the git index lock so the guard's restore genuinely fails.
            fs::write(self.source_root.join("tracked.txt"), b"coder mutation").unwrap();
            fs::write(self.source_root.join(".git/index.lock"), b"held").unwrap();
            Err(anyhow::Error::new(
                crate::transcript_pump::TranscriptPumpError::new(
                    "write transcript-pump status: no space left on device",
                ),
            ))
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the review route never runs interactively")
        }
    }

    struct ProviderOutageCoder {
        launches: Arc<Mutex<usize>>,
    }

    impl crate::coder::Coder for ProviderOutageCoder {
        fn run(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            _transcript_file: Option<&Path>,
        ) -> Result<i32> {
            unreachable!("the review route launches through run_captured")
        }

        fn run_captured(
            &self,
            _prompt: &str,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
            capture: Option<&crate::coder::TranscriptCapture<'_>>,
        ) -> Result<i32> {
            *self.launches.lock().unwrap() += 1;
            let transcript = capture
                .expect("task coder receives transcript capture")
                .path();
            let parent = transcript.parent().unwrap();
            fs::create_dir_all(parent).unwrap();
            for phase in 0..crate::coder::RATE_LIMIT_MAX_RETRIES {
                fs::write(
                    parent.join(format!("transcript.{phase}.jsonl")),
                    "{\"type\":\"rate_limit_event\",\"retry_after\":1}\n",
                )
                .unwrap();
            }
            fs::write(
                transcript,
                "{\"type\":\"rate_limit_event\",\"retry_after\":1}\n",
            )
            .unwrap();
            Ok(1)
        }

        fn run_interactive(
            &self,
            _system_prompt: &str,
            _working_dir: &Path,
            _extra_args: &[String],
            _extra_env: &[(String, String)],
        ) -> Result<i32> {
            unreachable!("the review route never runs interactively")
        }
    }

