    #[test]
    fn reviewer_route_composes_pump_and_confinement_restore_failure() {
        // B7: the FULL Reviewer route — real reservation, post-reservation setup, the
        // real source-checkout confinement guard, retry decision, and composed
        // terminalization — when the injected reviewer coder faults with a typed
        // transcript-pump primary AND has mutated a tracked source file while holding
        // the git index lock, so the guard's real RESTORE fails. The composed outcome
        // preserves the typed pump primary (still downcastable, classifying a resumable
        // pump pause), retains the confinement restore failure as secondary context,
        // does NOT retry the pump fault, and durably terminalizes the Task and Attempt
        // to NeedsUser — never fabricated finalizer inputs.
        let tmp = tempfile::TempDir::new().unwrap();
        let project_root = tmp.path().join("project");
        let project_root = project_root.as_path();
        fs::create_dir_all(project_root).unwrap();
        let git = |args: &[&str]| {
            crate::git::run(project_root, args, "test git setup").unwrap();
        };
        git(&["init", "-q", "-b", "main"]);
        git(&["config", "user.email", "t@t.co"]);
        git(&["config", "user.name", "t"]);
        fs::write(project_root.join("tracked.txt"), b"original").unwrap();
        fs::write(
            project_root.join("Cargo.toml"),
            "[package]\nname = \"terminal-cache\"\nversion = \"0.1.0\"\nedition = \"2024\"\n",
        )
        .unwrap();
        fs::create_dir_all(project_root.join("target")).unwrap();
        fs::write(project_root.join("target/output"), "candidate cache").unwrap();
        fs::create_dir_all(project_root.join(".fluent")).unwrap();
        fs::write(
            project_root.join(".fluent/config.yaml"),
            "reviewer-cache:\n  max-project-gib: 1\n  min-free-gib: 0\n",
        )
        .unwrap();
        git(&["add", "."]);
        git(&["commit", "-q", "-m", "baseline"]);
        let head = crate::git::run_stdout(project_root, &["rev-parse", "HEAD"], "head").unwrap();

        // A ReviewOnly source-checkout attempt: the readable workspace IS the project
        // root at HEAD, so run_review_task uses the SourceCheckoutReviewGuard.
        let store = WorkModelStore::new(project_root);
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Reviewer confinement restore failure".to_string(),
            ..Default::default()
        };
        item.add_review_only_attempt("attempt-1", &["architecture"], "main", head.trim(), true)
            .unwrap();
        let review_task_id = "attempt-1-review-architecture".to_string();
        store.create_work_item(&item).unwrap();

        let resolver = ContentResolver::new(Some(project_root));
        let launches = Arc::new(Mutex::new(0usize));
        let source_root = project_root.to_path_buf();
        let launches_for_coder = Arc::clone(&launches);
        let make_coder = move |_sandbox: CoderSandbox| -> Box<dyn crate::coder::Coder> {
            Box::new(SourceRestoreFaultCoder {
                source_root: source_root.clone(),
                launches: Arc::clone(&launches_for_coder),
            })
        };
        let error = run_review_task_with_coder(
            WorkTaskRunConfig {
                project_root,
                store: &store,
                work_item_id: "work-1",
                attempt_id: "attempt-1",
                task_id: &review_task_id,
                resolver: &resolver,
                extra_args: &[],
                no_sandbox: true,
                store_lock: None,
            },
            Some(&make_coder),
            &FilesystemReviewerCacheAdmission,
            &report_reviewer_cache,
        )
        .expect_err("a composite coder+confinement-restore failure must return an error");

        // The typed pump primary survives composition through the real route.
        assert!(
            error
                .downcast_ref::<crate::transcript_pump::TranscriptPumpError>()
                .is_some(),
            "the transcript-pump primary must remain discoverable by downcast: {error:#}"
        );
        // The real confinement restore failure is retained as a downcastable typed
        // secondary — not flattened into a rendered string — so both the pump primary
        // and the confinement failure survive composition.
        assert!(
            error.downcast_ref::<ReviewerConfinementError>().is_some(),
            "the confinement cleanup failure must remain discoverable by downcast: {error:#}"
        );
        let rendered = format!("{error:#}");
        assert!(
            rendered.contains("confinement") && rendered.to_lowercase().contains("restore"),
            "the confinement RESTORE failure must be retained as secondary context: {rendered}"
        );
        // The pump fault is not retried: the coder launched exactly once.
        assert_eq!(
            *launches.lock().unwrap(),
            1,
            "a transcript-pump fault must not spawn a retry coder"
        );

        // The Task AND Attempt are durably terminalized as a resumable transcript-pump
        // pause, classified from the preserved typed primary — never left Executing.
        let after = store.read_work_item("work-1").unwrap();
        let review = after.attempts[0]
            .tasks
            .iter()
            .find(|t| t.id == review_task_id)
            .unwrap();
        assert_eq!(
            review.status,
            TaskStatus::NeedsUser,
            "the Review Task is durably terminalized through the real route, never left Executing"
        );
        let artifact_dir = project_root.join(crate::work_model::work_artifact_path(
            "work-1",
            "attempt-1",
            &review_task_id,
        ));
        assert!(
            !artifact_dir.join("target").exists(),
            "NeedsUser Reviewer settlement must reclaim the admitted canonical cache"
        );
        assert!(
            project_root
                .join(crate::work_model::work_artifact_path(
                    "work-1",
                    "attempt-1",
                    "needs-user-attempt-1-review-architecture.md",
                ))
                .is_file(),
            "terminal cleanup must retain the NeedsUser handoff evidence"
        );
        assert_eq!(
            after.attempts[0].status,
            AttemptStatus::NeedsUser,
            "the Attempt is paused, never left Reviewing"
        );
        assert_eq!(
            after.attempts[0].pause_kind,
            Some(crate::work_model::PauseKind::TranscriptPump),
            "the preserved typed pump primary classifies the pause, not the confinement failure"
        );
        // The lock residue is real: the coder's git-index lock is still present.
        assert!(
            project_root.join(".git/index.lock").exists(),
            "the held git index lock is real residue the restore could not clear"
        );
        // The failed restore genuinely left the coder's tracked-file mutation on disk,
        // proving the guard could not roll the source checkout back.
        assert_eq!(
            fs::read(project_root.join("tracked.txt")).unwrap(),
            b"coder mutation",
            "the failed restore left the coder's tracked mutation, not the baseline"
        );
    }

    struct ReviewCompletionFixture {
        _tmp: tempfile::TempDir,
        project_root: PathBuf,
        store: WorkModelStore,
        candidate_commit: String,
        artifact_dir: PathBuf,
    }

    impl ReviewCompletionFixture {
        fn new() -> Self {
            Self::new_with_mode(crate::work_model::TerminalMode::Headless)
        }

        fn new_native_claude() -> Self {
            Self::new_with_mode(crate::work_model::TerminalMode::Native)
        }

        fn new_with_mode(terminal_mode: crate::work_model::TerminalMode) -> Self {
            let tmp = tempfile::TempDir::new().unwrap();
            let project_root = tmp.path().join("project");
            fs::create_dir_all(project_root.join("src")).unwrap();
            git::run(
                &project_root,
                &["init", "-q", "-b", "main"],
                "initialize fixture",
            )
            .unwrap();
            fs::write(project_root.join("src/lib.rs"), "pub fn reviewed() {}\n").unwrap();
            git::run(&project_root, &["add", "src/lib.rs"], "stage fixture").unwrap();
            git::run(
                &project_root,
                &[
                    "-c",
                    "user.name=Test",
                    "-c",
                    "user.email=test@example.invalid",
                    "commit",
                    "-q",
                    "-m",
                    "fixture",
                ],
                "commit fixture",
            )
            .unwrap();
            let candidate_commit =
                git::run_stdout(&project_root, &["rev-parse", "HEAD"], "read HEAD").unwrap();

            let artifact_area =
                work_artifact_path("work-1", "attempt-1", "attempt-1-review-architecture");
            let artifact_dir = project_root.join(&artifact_area);
            fs::create_dir_all(&artifact_dir).unwrap();
            let mut item = WorkItem {
                id: "work-1".to_string(),
                title: "Review inspection fixture".to_string(),
                ..Default::default()
            };
            item.add_initial_attempt("attempt-1").unwrap();
            item.attempts[0].terminal_mode = terminal_mode;
            let task = &mut item.attempts[0].tasks[0];
            task.id = "attempt-1-review-architecture".to_string();
            task.kind = TaskKind::Review;
            task.role = "architecture".to_string();
            task.status = TaskStatus::Executing;
            task.workspace_access.writes.clear();
            task.workspace_access.reads = vec![WorkspaceRef {
                id: "candidate".to_string(),
                path: ".".to_string(),
            }];
            task.artifact_area = Some(crate::work_model::TaskArtifactArea {
                path: artifact_area,
            });
            task.review_context = Some(crate::work_model::ReviewContext {
                candidate_workspace_id: "candidate".to_string(),
                candidate_workspace_path: ".".to_string(),
                source_branch: "main".to_string(),
                candidate_commit: candidate_commit.clone(),
                base_commit: None,
            });
            task.output = None;
            item.attempts[0].status = AttemptStatus::Reviewing;
            let store = WorkModelStore::new(&project_root);
            store.create_work_item(&item).unwrap();

            Self {
                _tmp: tmp,
                project_root,
                store,
                candidate_commit,
                artifact_dir,
            }
        }

        fn config<'a>(&'a self, resolver: &'a ContentResolver) -> WorkTaskRunConfig<'a> {
            WorkTaskRunConfig {
                project_root: &self.project_root,
                store: &self.store,
                work_item_id: "work-1",
                attempt_id: "attempt-1",
                task_id: "attempt-1-review-architecture",
                resolver,
                extra_args: &[],
                no_sandbox: true,
                store_lock: None,
            }
        }

        fn write_valid_passing_artifacts(&self) {
            fs::write(
                self.artifact_dir.join("review.md"),
                "Verdict: pass\n\n## Findings\n",
            )
            .unwrap();
            fs::write(
                self.artifact_dir
                    .join(crate::review_inspection::REVIEW_INSPECTION_FILE),
                serde_json::to_vec_pretty(&serde_json::json!({
                    "schema-version": 1,
                    "candidate-commit": self.candidate_commit,
                    "role": "architecture",
                    "inspections": [{
                        "path": "src/lib.rs",
                        "summary": "Checked the public module boundary."
                    }]
                }))
                .unwrap(),
            )
            .unwrap();
            fs::write(
                self.artifact_dir.join("transcript.jsonl"),
                format!(
                    "{{\"type\":\"item.completed\",\"item\":{{\"type\":\"command_execution\",\"status\":\"completed\",\"exit_code\":0,\"command\":\"sed -n 1,40p {}\"}}}}\n",
                    self.project_root.join("src/lib.rs").display()
                ),
            )
            .unwrap();
        }
    }

