    #[test]
    fn attempt_stop_blocks_reserved_peer_while_another_worker_settles() {
        use crate::execution::{self, ExecutionRecord, ExecutionState};
        use std::sync::mpsc;
        use std::time::{Duration, Instant};

        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        let store = WorkModelStore::new(root);
        let mut item = review_item();
        item.add_review_tasks("attempt-1", &["behaviors"]).unwrap();
        store.create_work_item(&item).unwrap();
        let reserve = |task: &str| {
            reserve_task_start(
                root,
                &store,
                "work-1",
                "attempt-1",
                task,
                TaskKind::Review,
                AttemptStatus::Reviewing,
                CoderKind::Claude,
            )
            .unwrap()
        };
        let a = reserve("attempt-1-review-tests");
        let b = reserve("attempt-1-review-behaviors");
        let a_transcript = root
            .join(&a.task.artifact_area.unwrap().path)
            .join("transcript.jsonl");
        let b_transcript = root
            .join(&b.task.artifact_area.unwrap().path)
            .join("transcript.jsonl");
        let a_record = execution::record_path_for_transcript(&a_transcript);
        let b_record = execution::record_path_for_transcript(&b_transcript);
        let a_ready = root.join("a-ready");
        let a_stopping = root.join("a-stopping");
        let a_release = root.join("a-release");
        let b_marker = root.join("b-started");
        let wait_for = |path: &Path, timeout: Duration| {
            let deadline = Instant::now() + timeout;
            while !path.is_file() && Instant::now() < deadline {
                std::thread::sleep(Duration::from_millis(5));
            }
            assert!(path.is_file(), "fixture barrier {}", path.display());
        };
        let a_lease =
            crate::lease::acquire(&crate::lease::task_lock_path(root, "work-1", &a.task.id))
                .unwrap();
        let b_lease =
            crate::lease::acquire(&crate::lease::task_lock_path(root, "work-1", &b.task.id))
                .unwrap();
        std::thread::scope(|scope| {
            let a_worker = scope.spawn(|| {
                let _lease = a_lease;
                let mut command = std::process::Command::new("python3");
                command
                    .args([
                        "-c",
                        r#"
import pathlib, signal, sys, time
ready, stopping, release = map(pathlib.Path, sys.argv[1:])
deadline = time.monotonic() + 10
def stop(*_):
    stopping.touch()
    while not release.exists() and time.monotonic() < deadline:
        time.sleep(.005)
    sys.exit(0)
signal.signal(signal.SIGTERM, stop)
ready.touch()
while time.monotonic() < deadline:
    time.sleep(.005)
"#,
                    ])
                    .arg(&a_ready)
                    .arg(&a_stopping)
                    .arg(&a_release);
                execution::output(&mut command, &a_transcript)
            });
            let (release_b, wait_b) = mpsc::channel();
            let b_worker = scope.spawn({
                let b_marker = &b_marker;
                let b_transcript = &b_transcript;
                move || {
                    let _lease = b_lease;
                    wait_b.recv_timeout(Duration::from_secs(5)).unwrap();
                    let mut command = std::process::Command::new("touch");
                    command.arg(&b_marker);
                    execution::output(&mut command, &b_transcript)
                }
            });
            wait_for(&a_ready, Duration::from_secs(5));
            let cancel = scope.spawn(|| {
                crate::work_attempt_loop::cancel_local_attempt(root, &store, "work-1", "attempt-1")
            });
            wait_for(&a_stopping, Duration::from_secs(1));
            let stopped = store.read_work_item("work-1").unwrap();
            assert!(stopped.attempts[0].cancellation_requested());
            assert!(
                stopped.attempts[0]
                    .cancellation
                    .as_ref()
                    .unwrap()
                    .settled_at
                    .is_none()
            );
            assert_eq!(
                serde_json::from_slice::<ExecutionRecord>(&fs::read(&b_record).unwrap())
                    .unwrap()
                    .state,
                ExecutionState::Launching,
                "cancellation has not visited B yet"
            );
            release_b.send(()).unwrap();
            let result = b_worker.join().unwrap();
            assert!(
                execution::execution_is_live(&a_record).unwrap(),
                "A must still hold its execution identity at the termination barrier"
            );
            assert!(
                result.is_err(),
                "the shared stop must reject B before cancellation visits its record"
            );
            assert!(
                !b_marker.exists(),
                "B must never start after the Attempt stop commits"
            );
            fs::write(&a_release, b"release").unwrap();
            a_worker.join().unwrap().unwrap();
            cancel.join().unwrap().unwrap();
        });
        assert!(!execution::execution_is_live(&a_record).unwrap());
        let stopped = store.read_work_item("work-1").unwrap();
        assert!(
            stopped.attempts[0]
                .cancellation
                .as_ref()
                .unwrap()
                .settled_at
                .is_some()
        );
        assert_eq!(
            stopped.attempts[0].pause_kind,
            Some(crate::work_model::PauseKind::Interrupted)
        );
    }

    #[test]
    fn task_execution_identity_precedes_executing_state_and_honors_stop() {
        let tmp = tempfile::tempdir().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = WorkItem::planned("work-1", "Guard child launch");
        item.add_initial_attempt("attempt-1").unwrap();
        store.create_work_item(&item).unwrap();
        let reserved = reserve_task_start(
            tmp.path(),
            &store,
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            TaskKind::Write,
            AttemptStatus::Executing,
            CoderKind::Claude,
        )
        .unwrap();
        let path = crate::execution::record_path_for_artifact(
            tmp.path(),
            &reserved.task.artifact_area.unwrap().path,
        );
        assert!(
            path.is_file(),
            "executing Task must already have a cancellable identity"
        );
        crate::work_attempt_loop::cancel_local_attempt(tmp.path(), &store, "work-1", "attempt-1")
            .unwrap();
        let marker = tmp.path().join("launched");
        let mut command = std::process::Command::new("touch");
        command.arg(&marker);
        // All production launchers cross this same guarded boundary.
        assert!(
            crate::execution::spawn(&mut command, &path.with_file_name("transcript.jsonl"))
                .is_err()
        );
        assert!(!marker.exists());
    }

    #[test]
    fn atomic_start_serializes_against_a_concurrent_peer_terminal() {
        // A barriered race: one thread pauses the Attempt while another reserves a
        // start, both transacting under the cross-process model lock. Whichever the
        // lock admits first wins; the start either fully commits Executing or
        // cleanly rejects with StartRejected, but never revives an Attempt a peer
        // paused nor tears the aggregate.
        use std::sync::{Arc, Barrier};

        let tmp = tempfile::TempDir::new().unwrap();
        let project_root = tmp.path();
        let store = WorkModelStore::new(project_root);
        let mut item = WorkItem {
            id: "work-1".to_string(),
            title: "Serialize starts against peer terminals".to_string(),
            planning_context: None,
            instructions: None,
            abandonment: None,
            post_merge_review_fix_depth: None,
            attempts: Vec::new(),
            merge_candidates: Vec::new(),
            ..Default::default()
        };
        item.add_initial_attempt("attempt-1").unwrap();
        store.create_work_item(&item).unwrap();

        let barrier = Arc::new(Barrier::new(2));

        std::thread::scope(|scope| {
            let pauser_barrier = Arc::clone(&barrier);
            let store_ref = &store;
            scope.spawn(move || {
                pauser_barrier.wait();
                store_ref
                    .mutate_work_item("work-1", |item| {
                        crate::work_model::transition_attempt(
                            &mut item.attempts[0],
                            AttemptStatus::NeedsUser,
                            Some(crate::work_model::PauseKind::TranscriptPump),
                        );
                        Ok(())
                    })
                    .unwrap();
            });

            let starter_barrier = Arc::clone(&barrier);
            let starter = scope.spawn(move || {
                starter_barrier.wait();
                reserve_task_start(
                    project_root,
                    store_ref,
                    "work-1",
                    "attempt-1",
                    "attempt-1-write-1",
                    TaskKind::Write,
                    AttemptStatus::Executing,
                    CoderKind::Claude,
                )
            });
            let start_result = starter.join().unwrap();

            let stored = store_ref.read_work_item("work-1").unwrap();
            match start_result {
                Ok(_reservation) => {
                    // The start won the lock first: the Task is Executing and the
                    // pauser's later transition cannot downgrade it below active.
                    assert_eq!(stored.attempts[0].tasks[0].status, TaskStatus::Executing);
                }
                Err(error) => {
                    // The pause won first: the start rejected cleanly and left the
                    // pause intact — never a revived, torn state.
                    assert!(is_start_rejected(&error), "unexpected error: {error}");
                    assert_eq!(stored.attempts[0].status, AttemptStatus::NeedsUser);
                    assert_eq!(
                        stored.attempts[0].pause_kind,
                        Some(crate::work_model::PauseKind::TranscriptPump)
                    );
                    assert_eq!(stored.attempts[0].tasks[0].status, TaskStatus::Planned);
                }
            }
        });
    }

    #[test]
    fn corrective_writer_does_not_recapture_attempt_baseline_without_tester() {
        let tmp = tempfile::TempDir::new().unwrap();
        let store = WorkModelStore::new(tmp.path());
        let mut item = review_item();
        item.attempts[0].status = AttemptStatus::Planned;
        let task_id = item.add_next_write_round("attempt-1", Vec::new()).unwrap();
        store.create_work_item(&item).unwrap();

        let reservation = reserve_task_start(
            tmp.path(),
            &store,
            "work-1",
            "attempt-1",
            &task_id,
            TaskKind::Write,
            AttemptStatus::Executing,
            CoderKind::Claude,
        )
        .unwrap();

        assert!(
            !reservation.is_first_write,
            "a corrective Writer must reuse the Attempt baseline even when no final Tester exists"
        );
        let transition = store
            .read_work_item("work-1")
            .unwrap()
            .transitions
            .last()
            .cloned()
            .unwrap();
        assert_eq!(transition.object_kind, "task");
        assert_eq!(transition.object_id, task_id);
        assert_eq!(transition.origin, DurableTransitionOrigin::TaskExecutor);
        assert_eq!(transition.reason, None);
    }

    fn corrective_review_item(role: &str) -> WorkItem {
        let context = CorrectiveContext {
            objective: "Restore the retry guard".to_string(),
            requirement: "Retries stop after the configured cap".to_string(),
            evidence: "Merged commit abc123 removed the cap check".to_string(),
            included_scope: "src/retry.rs".to_string(),
            excluded_scope: "unrelated backoff tuning".to_string(),
            verification: "cargo test retry::cap_is_enforced".to_string(),
        };
        let mut item = WorkItem::derived_corrective(
            "work-1",
            "Restore the retry guard",
            DerivedProvenance::default(),
            context,
            WorkLineage::descendant_of("root-1", None),
            Some(ExecutionAuthority::Automatic),
        )
        .unwrap();
        item.corrective_audit = Some(CorrectiveAuditContext {
            follow_up_id: "fu-retry-cap".to_string(),
            source: "learner".to_string(),
            summary: "Restore the retry guard".to_string(),
            learning_summary: "The accepted change removed the retry cap".to_string(),
            expected_result: "The retry cap is enforced again".to_string(),
            target_paths: vec!["src/retry.rs".to_string()],
            unresolved_decisions: Vec::new(),
            authority: CorrectiveAuthorityReference {
                kind: "expertise-entry".to_string(),
                path: ".fluent/expertise/retry.md".to_string(),
                anchor: "Retries stop after the configured cap".to_string(),
                digest: "sha256:authority".to_string(),
            },
            evidence: vec![CorrectiveEvidenceReference {
                path: "review.md".to_string(),
                digest: "sha256:evidence".to_string(),
            }],
        });
        item.add_initial_attempt("attempt-1").unwrap();
        let attempt = item.attempts.first_mut().unwrap();
        let task = attempt.tasks.first_mut().unwrap();
        let workspace = task.workspace_access.writes.first().unwrap().clone();
        task.status = TaskStatus::Complete;
        task.output = Some(TaskOutput {
            workspace_id: workspace.id,
            workspace_path: workspace.path,
            source_branch: "main".to_string(),
            base_commit: None,
            commit: "abc123".to_string(),
            no_change: None,
            learner_canonicalization: None,
        });
        item.add_review_tasks("attempt-1", &[role]).unwrap();
        item
    }

    #[test]
    fn corrective_prompts_and_task_records_retain_execution_context() {
        let tmp = tempfile::TempDir::new().unwrap();
        let project_root = tmp.path();
        let workspace = tmp.path().join("work-6-work-1-attempt-1");
        fs::create_dir_all(&workspace).unwrap();

        let mut item = corrective_review_item("tests");
        item.add_final_tester_task("attempt-1").unwrap();
        let context = item.write_task_instructions().unwrap();

        // The Writer receives the corrective execution context verbatim.
        let write_prompt = build_write_task_prompt_with_workspace(
            &item,
            "attempt-1",
            "attempt-1-write-1",
            &[],
            Some(&workspace),
            Some(project_root),
        );

        // Every reviewer receives the same corrective execution context.
        let artifact_dir =
            project_root.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-review-tests");
        let review_path = artifact_dir.join("review.md");
        let prompts = build_work_review_prompts(WorkReviewPromptInput {
            item: &item,
            attempt_id: "attempt-1",
            task_id: "attempt-1-review-tests",
            project_root,
            artifact_dir: &artifact_dir,
            review_path: &review_path,
            readable_workspaces: std::slice::from_ref(&workspace),
            input_artifacts: &[],
            review_only: false,
        })
        .unwrap();

        assert!(
            write_prompt.contains(&context),
            "writer prompt must contain the corrective execution context"
        );
        assert!(
            prompts.review_prompt.contains(&context),
            "reviewer prompt must contain the same corrective execution context"
        );
        for probe in [
            "Restore the retry guard",
            "Retries stop after the configured cap",
            "cargo test retry::cap_is_enforced",
            "The retry cap is enforced again",
            "src/retry.rs",
            ".fluent/expertise/retry.md",
            "sha256:evidence",
            "The accepted change removed the retry cap",
        ] {
            assert!(write_prompt.contains(probe), "writer missing {probe:?}");
            assert!(
                prompts.review_prompt.contains(probe),
                "reviewer missing {probe:?}"
            );
        }

        // The Tester Task persists the same context for durable inspection, but
        // its runner executes tester.yaml rather than consuming a prompt.
        let tester = item.attempts[0]
            .tasks
            .iter()
            .find(|task| task.kind == TaskKind::Tester)
            .expect("corrective Attempt has a Tester Task");
        assert_eq!(tester.instructions.as_deref(), Some(context.as_str()));
    }

